package net.officefloor.hq.app.claim;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import org.hibernate.annotations.Generated;
import org.hibernate.generator.EventType;

/**
 * A claim by a person on a sheet: an amount (two decimals), a date, a note and a status (DRAFT when
 * added), and a number and who opened it once opened. A negative amount makes it a correction, which
 * names the number of the SETTLED claim of its person that it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    /** The kinds a proof can be; a proof added with none chosen is a receipt. */
    public static final String PROOF_RECEIPT = "receipt", PROOF_PHOTO = "photo";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    /**
     * Its place in its sheet's list, newest (highest) first: the next of claim_listed_seq, given by the
     * store when added and again when moved to another person.
     */
    @Generated(event = EventType.INSERT)
    @Column(name = "listed", insertable = false)
    private Long listed;

    /**
     * Its place in the order claims were added to their sheets: the next of claim_added_seq, given by the
     * store when added and again when it arrives on another sheet. A forward-only rate applies only to
     * claims added after it was saved.
     */
    @Generated(event = EventType.INSERT)
    @Column(name = "added", insertable = false)
    private Long added;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    /**
     * The date it is due by, fixed when added: the terms-th business day after its date, with its person's own
     * terms, else those of their grade then. Fixed again, with the same terms, when a holiday is added.
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms, in business days, its due-by was fixed with. */
    @Column(name = "terms", nullable = false, updatable = false)
    private int terms;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /**
     * Given when the claim is opened: the sheet-wide number, or <period name>-<n> (X-<n> in no
     * period) while the sheet numbers by period; none while DRAFT, kept when VOID.
     */
    @Column(name = "claim_number")
    private String number;

    /** The period the claim was numbered within (empty: in no period); none unless numbered by period. */
    @Column(name = "number_period")
    private String numberPeriod;

    /** The claim's place in its period's numbering; none unless numbered by period. */
    @Column(name = "number_seq")
    private Integer numberSeq;

    /** The user who opened the claim; none while DRAFT. */
    @Column(name = "opened_by", length = 100)
    private String openedBy;

    /** The user who last edited the claim; none while never edited. */
    @Column(name = "edited_by", length = 100)
    private String editedBy;

    /** The due fixed when the claim was settled; none while not settled, or settled with no rate. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** Bound by its person's last statement, which it counted toward; its due is then {@link #statedDue}. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /**
     * The due it had as shown at its person's last statement, late charge and floor included; none while not
     * stated, or stated with no due.
     */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this correction corrects; none unless a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** Its external reference, trimmed; none unless given. Unique on the sheet by its {@link #refKeyOf key}. */
    @Column(name = "ref", length = 200)
    private String ref;

    /** Its reference lower-cased, the key its uniqueness on the sheet is kept on; none without a reference. */
    @Column(name = "ref_key", length = 200)
    private String refKey;

    /** Its tags, sorted and comma separated (see {@link #tagsOf}); empty for none. */
    @Column(name = "tags", nullable = false, length = 2000)
    private String tags = "";

    /** The number of the claim it was split from; none unless split off one. */
    @Column(name = "split_from")
    private String splitFrom;

    /** How many proofs it has; raised one at a time while not SETTLED or VOID. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** How many of its proofs are receipts. */
    @Column(name = "proofs_receipt", nullable = false)
    private int proofsReceipt;

    /** How many of its proofs are photos. */
    @Column(name = "proofs_photo", nullable = false)
    private int proofsPhoto;

    /** The date it is deferred until; none unless deferred. Deferred only while OPEN and before that date. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The reason it was voided with, from the sheet's list; none unless voided with one. */
    @Column(name = "void_reason", length = 200)
    private String voidReason;

    /** The sheet's today when it was deferred; none unless deferred (or deferred before this was kept). */
    @Column(name = "deferred_on")
    private LocalDate deferredOn;

    /** Whether it was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The user whose open editor locks it for everyone else; none while no editor holds it. */
    @Column(name = "locked_by", length = 100)
    private String lockedBy;

    /** The last sheet's today a reminder was written for it; none until reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Whether a reminder has escalated it; a claim is escalated at most once. */
    @Column(name = "escalated", nullable = false)
    private boolean escalated;

    /** Whether a steward waived its late charge; a claim is waived at most once. */
    @Column(name = "waived", nullable = false)
    private boolean waived;

    /** Whether it is held: it still counts in every figure. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The sheet's today when its late charge was waived; none unless waived. */
    @Column(name = "waived_on")
    private LocalDate waivedOn;

    /** The sheet's today when it last went to REVIEW; none unless it has. */
    @Column(name = "review_on")
    private LocalDate reviewOn;

    /** The number of the bulk settle batch that settled it (or sent it to PENDING); none when settled one at a time. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** Its status log, oldest first: a line for each status it has had, DRAFT when added. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimLogEntry> log = new ArrayList<>();

    /** Its binding log, oldest first: a line each time a statement bound it or it was left unbound again. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_binding", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimBinding> bindings = new ArrayList<>();

    /** Its comments, oldest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_comment", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimComment> comments = new ArrayList<>();

    /** Its lines, in the order they were added; with any, its amount is what they add up to. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "claim_line", joinColumns = @JoinColumn(name = "claim_id"))
    @OrderColumn(name = "seq")
    private List<ClaimLine> lines = new ArrayList<>();

    protected Claim() {}

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy,
            int terms) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.dueBy = dueBy;
        this.terms = terms;
    }

    public Long getId() { return id; }

    /** A correction: a negative amount. Its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }

    public String getCorrects() { return corrects; }

    public void setCorrects(String corrects) { this.corrects = corrects; }

    public String getRef() { return ref; }

    /** Give it an external reference (null: none). */
    public void setRef(String ref) {
        this.ref = ref;
        this.refKey = ref == null ? null : refKeyOf(ref);
    }

    /** The key a reference is compared on: trimmed, without regard to case. */
    public static String refKeyOf(String ref) {
        return ref.strip().toLowerCase(Locale.ROOT);
    }

    /** Its tags, sorted; empty for none. */
    public List<String> getTags() {
        return tags.isEmpty() ? List.of() : List.of(tags.split(","));
    }

    /** Give it tags, as {@link #tagsOf} reads them. */
    public void setTags(List<String> tags) {
        this.tags = String.join(",", tagsOf(tags));
    }

    /** Tags each trimmed and lower-cased, blanks and repeats dropped, sorted. */
    public static List<String> tagsOf(List<String> tags) {
        return tags.stream().map(t -> t.strip().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                .distinct().sorted().toList();
    }

    /** The tags in comma separated text, as {@link #tagsOf} reads them; none for null. */
    public static List<String> tagsOf(String text) {
        return text == null ? List.of() : tagsOf(List.of(text.split(",")));
    }

    public String getSplitFrom() { return splitFrom; }

    public String getVoidReason() { return voidReason; }

    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }

    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public Long getListed() { return listed; }

    /** Its place in the order claims were added; null until the store has added it (then it is the newest). */
    public Long getAdded() { return added; }

    /** Move the claim to another person, listed as their newest at the given place in the list. */
    public void moveTo(Long personId, long listed) {
        this.personId = personId;
        this.listed = listed;
    }

    /**
     * Move the claim, with its person, to another sheet: it keeps its status, dates, note, tags, frozen
     * figure, logs and any figure a statement bound it to, but loses its reference, its number (to be
     * given the other sheet's next), its settle batch and any editor's lock; it is added to the other sheet
     * at the given place in the order claims were added.
     */
    public void transferTo(String sheetId, long added) {
        this.sheetId = sheetId;
        this.added = added;
        setRef(null);
        this.number = null;
        this.numberPeriod = null;
        this.numberSeq = null;
        this.settleBatch = null;
        this.lockedBy = null;
    }

    /** The sheet's today it was first opened on, as its status log records it; null when it records none. */
    public LocalDate openedOn() {
        for (ClaimLogEntry line : log) if (line.getStatus() == ClaimStatus.OPEN) return line.getDate();
        return null;
    }

    public BigDecimal getAmount() { return amount; }

    public void setAmount(BigDecimal amount) { this.amount = amount; }

    public LocalDate getDate() { return date; }

    public void setDate(LocalDate date) { this.date = date; }

    public String getNote() { return note; }

    /** The date it is due by, fixed when added; it does not move with its date or the terms, only when a holiday is added. */
    public LocalDate getDueBy() { return dueBy; }

    /** Fix the due-by again, as worked out over the sheet's holidays now. */
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }

    /** The terms, in business days, its due-by was fixed with. */
    public int getTerms() { return terms; }

    public void setNote(String note) { this.note = note; }

    public ClaimStatus getStatus() { return status; }

    public void setStatus(ClaimStatus status) { this.status = status; }

    public List<ClaimComment> getComments() { return Collections.unmodifiableList(comments); }

    /** Add a comment written by the user on the date. */
    public void comment(String by, LocalDate on, String text) {
        comments.add(new ClaimComment(by, on, text));
    }

    public List<ClaimLine> getLines() { return Collections.unmodifiableList(lines); }

    /** Add a line; its amount becomes the quantities times the unit amounts added up. */
    public void addLine(String label, int qty, BigDecimal unit) {
        lines.add(new ClaimLine(label, qty, unit));
        amount = lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
    }

    public List<ClaimLogEntry> getLog() { return Collections.unmodifiableList(log); }

    /** Log the status it now has, given by the user on the date, with its due at that moment. */
    public void logStatus(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogEntry(status, by, on, due));
    }

    /**
     * The status it had at the end of the date, as its log records it: the last line dated on or before
     * it; null when it had none then (added after it). With no log lines (added before the log was
     * kept) it is taken to have had its status now.
     */
    public ClaimStatus statusAt(LocalDate date) {
        if (log.isEmpty()) return status;
        ClaimStatus at = null;
        for (ClaimLogEntry line : log) if (!line.getDate().isAfter(date)) at = line.getStatus();
        return at;
    }

    /**
     * The due it was settled at, as its status log records it, when SETTLED at the end of the date: the
     * due of its last SETTLED line dated on or before it; with no log lines, its settled due now.
     */
    public BigDecimal settledDueAt(LocalDate date) {
        if (log.isEmpty()) return settledDue;
        BigDecimal due = null;
        for (ClaimLogEntry line : log) {
            if (!line.getDate().isAfter(date) && line.getStatus() == ClaimStatus.SETTLED) due = line.getDue();
        }
        return due;
    }

    /** The date it was last settled, as its status log records it; null when the log has no SETTLED line. */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogEntry line : log) if (line.getStatus() == ClaimStatus.SETTLED) on = line.getDate();
        return on;
    }

    /** The sheet's today it was last deleted on, as its status log records it; null when the log has no DELETED line. */
    public LocalDate deletedOn() {
        LocalDate on = null;
        for (ClaimLogEntry line : log) if (line.getStatus() == ClaimStatus.DELETED) on = line.getDate();
        return on;
    }

    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }

    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Locked by an open editor of a user other than this one. */
    public boolean isLockedAgainst(String user) { return lockedBy != null && !lockedBy.equals(user.strip()); }
    public LocalDate getRemindedOn() { return remindedOn; }
    /** Record a reminder written on the sheet's today. */
    public void remind(LocalDate on) { this.remindedOn = on; }
    public boolean isEscalated() { return escalated; }
    public LocalDate getReviewOn() { return reviewOn; }
    public void setReviewOn(LocalDate reviewOn) { this.reviewOn = reviewOn; }
    /** Record that a reminder escalated it. */
    public void escalate() { this.escalated = true; }
    public boolean isHeld() { return held; }
    /** Hold it, or release it when held. */
    public void toggleHeld() { this.held = !held; }
    public boolean isWaived() { return waived; }
    public LocalDate getWaivedOn() { return waivedOn; }
    /** Waive its late charge on the sheet's today. */
    public void waive(LocalDate on) {
        this.waived = true;
        this.waivedOn = on;
    }
    /** Whether its late charge was waived on or before the date: it bears none from then on. */
    public boolean isWaivedAt(LocalDate date) {
        return waived && (waivedOn == null || date == null || !waivedOn.isAfter(date));
    }
    public Integer getSettleBatch() { return settleBatch; }
    public void setSettleBatch(Integer settleBatch) { this.settleBatch = settleBatch; }
    public String getNumber() { return number; }

    /** Number the claim sheet-wide. */
    public void setNumber(long number) { this.number = String.valueOf(number); }

    /** Number the claim within a fiscal year: FY&lt;year&gt;-&lt;n&gt;. */
    public void setFiscalNumber(int year, long n) { this.number = "FY" + year + "-" + n; }

    /** Number the claim within a period (empty name: in no period): <period name>-<n>, or X-<n>. */
    public void setNumberWithin(String period, int seq) {
        this.numberPeriod = period;
        this.numberSeq = seq;
        this.number = (period.isEmpty() ? "X" : period) + "-" + seq;
    }

    /** The period the claim was numbered within (empty: in no period); null unless numbered by period. */
    public String getNumberPeriod() { return numberPeriod; }

    public Integer getNumberSeq() { return numberSeq; }

    public String getOpenedBy() { return openedBy; }

    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public String getEditedBy() { return editedBy; }

    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }

    /** Whether the user opened or last edited the claim, so may neither settle nor approve it. */
    public boolean isOpenedOrEditedBy(String user) {
        String name = user.strip();
        return name.equals(openedBy) || name.equals(editedBy);
    }

    public BigDecimal getSettledDue() { return settledDue; }

    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }

    public boolean isStated() { return stated; }

    public BigDecimal getStatedDue() { return statedDue; }

    /**
     * Whether its due is now bound by its person's last statement: stated, a PENDING claim like any other.
     */
    public boolean isBound() { return stated; }

    /** Bind the claim to a due (null: it has none) on the sheet's today, as its person's statement does. */
    public void state(BigDecimal due, LocalDate on) {
        if (!stated || !Objects.equals(statedDue, due)) bindings.add(new ClaimBinding(on, true, due));
        this.stated = true;
        this.statedDue = due;
    }

    /**
     * The binding it had at the end of the date, as its binding log records it: the last line dated on or
     * before it, null when unbound then. With no log lines it is taken to have had its binding now.
     */
    public ClaimBinding bindingAt(LocalDate date) {
        if (bindings.isEmpty()) return stated ? new ClaimBinding(date, true, statedDue) : null;
        ClaimBinding at = null;
        for (ClaimBinding line : bindings) if (!line.getDate().isAfter(date)) at = line;
        return at != null && at.isStated() ? at : null;
    }

    public int getProofs() { return proofs; }

    public int getProofsReceipt() { return proofsReceipt; }

    public int getProofsPhoto() { return proofsPhoto; }

    /** How many of its proofs are of the kind (receipt or photo). */
    public int proofsOf(String kind) {
        return switch (kind) {
            case PROOF_RECEIPT -> proofsReceipt;
            case PROOF_PHOTO -> proofsPhoto;
            default -> 0;
        };
    }

    /** Raise its proofs count, and that of the kind (receipt or photo), by one. */
    public void addProof(String kind) {
        proofs++;
        if (PROOF_PHOTO.equals(kind)) proofsPhoto++;
        else proofsReceipt++;
    }

    public LocalDate getDeferredUntil() { return deferredUntil; }

    /** Defer it until the date, on the sheet's today. */
    public void deferUntil(LocalDate deferredUntil, LocalDate on) {
        this.deferredUntil = deferredUntil;
        this.deferredOn = on;
    }

    /**
     * Whether it was deferred at the end of the date, with the status it had then: OPEN, deferred on or
     * before the date until a date after it.
     */
    public boolean isDeferredAt(ClaimStatus statusThen, LocalDate date) {
        return statusThen == ClaimStatus.OPEN && deferredUntil != null && date.isBefore(deferredUntil)
                && (deferredOn == null || !deferredOn.isAfter(date));
    }

    /**
     * Whether it is deferred on the date: OPEN, with a deferred-until date after it. A deferred claim counts
     * in no total, is not overdue, cannot be settled and is left unbound by a statement.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** Leave the claim unbound on the sheet's today, its due live again. */
    public void unstate(LocalDate on) {
        if (stated) bindings.add(new ClaimBinding(on, false, null));
        this.stated = false;
        this.statedDue = null;
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonWatch;
import net.officefloor.hq.app.person.PersonWatchRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
 * added with no date takes the entry date while one is set, else the sheet's today (an edit with none, the sheet's today). Its due-by is fixed when it is added: the terms-th business day
 * after its date (skipping weekends and the sheet's holidays then), with its person's own terms, else the terms in force on that date of its person's grade then (else the
 * sheet's terms in force on it); it does not
 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
 * the sheet's next number (or, while the sheet numbers by period, the next within its period), which it
 * keeps when voided and is never given again. Only a DRAFT claim
 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
 * bound by no statement, or void it within 7 days of its settlement: its frozen figure leaves every total
 * and it keeps its number. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
 * due is above the sheet's clerk limit (a steward can). A claim with no proofs whose due is above the proof threshold
 * in force on its date cannot be settled or approved by anyone, and one with an empty note whose due is above the
 * note threshold in force on its date cannot be opened. No claim whose due-by falls inside a closed period can
 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
 * or edited to a date after its person's retirement date. A claim with a negative amount is a
 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
 * A claim whose due is above the review threshold in force on its date goes to REVIEW when opened, with no
 * number, until a steward reviews it ({@link #review}).
 * A steward can re-date an OPEN or PENDING claim ({@link #redate}). A DRAFT claim can be deleted, and
 * restored to DRAFT on the same sheet's today ({@link #delete}, {@link #restore}).
 */
@Service
public class ClaimService {

    /** How many days after its settlement a steward may still void a SETTLED claim. */
    static final int VOID_SETTLED_DAYS = 7;

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateService rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final PeriodRepository periods;
    private final SettingService settings;
    private final PersonWatchRepository watches;
    private final HolidayService holidays;
    private final ClaimTagRepository tags;
    private final VoidReasonService voidReasons;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
            RollupService rollup, PeriodRepository periods, SettingService settings, PersonWatchRepository watches,
            HolidayService holidays, ClaimTagRepository tags, VoidReasonService voidReasons, Audit audit) {
        this.voidReasons = voidReasons;
        this.tags = tags;
        this.watches = watches;
        this.holidays = holidays;
        this.settings = settings;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Every tag ever used on a claim of the sheet, sorted. */
    @Transactional(readOnly = true)
    public List<String> tags(String sheetId) {
        return tags.findBySheetIdOrderByTagAsc(sheetId).stream().map(ClaimTag::getTag).toList();
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, List.of());
    }

    /**
     * Add a claim carrying an external reference (null: none) and tags (as {@link Claim#tagsOf} reads them);
     * a reference already on the sheet is refused.
     */
    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, List<String> tagged) {
        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        LocalDate on = dateOrEntryDate(sheetId, date);
        int terms = termsOf(sheetId, person, sheets.today(sheetId));
        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
        refuseIfClosed(sheetId, dueBy);
        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
        refuseUnlessCorrects(sheetId, personId, null, amount, corrects);
        refuseIfRefUsed(sheetId, null, ref);
        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy, terms);
        draft.setCorrects(corrects);
        draft.setRef(ref);
        draft.setTags(tagged);
        draft.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        Claim claim = claims.saveAndFlush(draft);
        logStatus(sheetId, user, person, claim);
        claim = claims.saveAndFlush(claim);
        record("CLAIM_ADDED", sheetId, user, person, claim, claim.getNumber(),
                (claim.getRef() != null ? " ref=" + claim.getRef() : "")
                + (claim.getTags().isEmpty() ? "" : " tags=" + String.join(",", claim.getTags())));
        keepTags(sheetId, claim);
        if (claim.isLateEntry()) record("LATE_ENTRY", sheetId, user, person, claim);
        rollup.recordChanges(sheetId, user, before);
        return claim;
    }

    @Transactional
    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, List<String> tagged) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimStatusRefusedException();
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
        LocalDate on = dateOrToday(sheetId, date);
        refuseIfClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
        refuseUnlessCorrects(sheetId, person.getId(), claim.getId(), amount, corrects);
        refuseIfRefUsed(sheetId, claim.getId(), ref);
        if (!claim.getLines().isEmpty() && amount.compareTo(claim.getAmount()) != 0) {
            throw new ClaimLinedAmountException();
        }
        claim.setAmount(amount);
        claim.setRef(ref);
        claim.setTags(tagged);
        claim.setCorrects(corrects);
        claim.setDate(on);
        claim.setNote(note);
        claim.setLockedBy(null);
        claim.setEditedBy(user.strip());
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_EDITED", sheetId, user, person, saved);
        keepTags(sheetId, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Open a claim's editor: the claim is locked for every other user until the editor is saved or
     * cancelled, or the sheet's today changes. A claim that cannot be edited (not DRAFT, or due inside a
     * closed period), or one another user's editor already locks, is refused and takes no lock.
     */
    @Transactional
    public Claim lock(String sheetId, String user, Long id) {
        // Locking the sheet first, so two users opening the same claim's editor at once take turns.
        sheets.lockForNumbering(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusRefusedException();
        refuseIfClosed(sheetId, claim.getDueBy());
        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
        claim.setLockedBy(user.strip());
        return claims.saveAndFlush(claim);
    }

    /** Cancel a claim's editor: the user's own lock on it is released; another user's is left as it is. */
    @Transactional
    public Claim unlock(String sheetId, String user, Long id) {
        sheets.lockForNumbering(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getLockedBy() == null || claim.isLockedAgainst(user)) return claim;
        claim.setLockedBy(null);
        return claims.saveAndFlush(claim);
    }

    @Transactional
    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
        return changeStatus(sheetId, user, id, next, null);
    }

    /**
     * Settle a claim as part of a bulk settle: by the rules of settling one, then given the bulk's
     * batch number, the sheet's next one when the bulk has none yet (its first claim settled).
     */
    @Transactional
    public Claim settleInBatch(String sheetId, String user, Long id, Integer batch) {
        Claim claim = changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null);
        claim.setSettleBatch(batch != null ? batch : sheets.lockForNumbering(sheetId).nextSettleBatch());
        return claims.saveAndFlush(claim);
    }

    /**
     * Settle a claim as of a date on or before the sheet's today, by the rules of settling one, its due
     * fixed at the figure given (its due as it stood at the end of that date, see
     * {@link ClaimSettleAsOfService}); its settle record names the date.
     */
    @Transactional
    public Claim settleAsOf(String sheetId, String user, Long id, LocalDate on, BigDecimal figure) {
        if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, false, new AsOf(on, figure));
    }

    /** A settle as of a date: the date and the claim's due as it stood at its end. */
    private record AsOf(LocalDate on, BigDecimal figure) {}

    /** Void a claim; while the sheet's list of void reasons is not empty, only with a reason on it. */
    @Transactional
    public Claim voidClaim(String sheetId, String user, Long id, String reason) {
        return changeStatus(sheetId, user, id, ClaimStatus.VOID, reason);
    }

    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason) {
        return changeStatus(sheetId, user, id, next, reason, false);
    }

    /**
     * Part-settle an OPEN claim: split the amount off it as {@link #split} does, then settle the new claim
     * by the user as settling one does (PENDING when over the clerk limit). The four-eyes rule and the proof
     * rule are judged on the original claim (its due before the split), not the new one the user opened; a
     * refusal of the split or the settle refuses the whole and changes nothing.
     */
    @Transactional
    public Split partSettle(String sheetId, String user, Long id, BigDecimal amount) {
        sheets.lockForNumbering(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
        if (!settings.mayDo(sheetId, user, "settle")) throw new ClaimNotPermittedException();
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimSettledByOpenerException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        refuseUnproved(sheetId, person, claim, chargedFigureOf(sheetId, person, claim));
        Split split = split(sheetId, user, id, amount);
        Claim settled = changeStatus(sheetId, user, split.split().getId(), ClaimStatus.SETTLED, null, true);
        return new Split(split.original(), settled);
    }

    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason,
            boolean judgedOnOriginal) {
        return changeStatus(sheetId, user, id, next, reason, judgedOnOriginal, null);
    }

    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason,
            boolean judgedOnOriginal, AsOf asOf) {
        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
        // once no other open on the sheet is under way; a refusal rolls the number back.
        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        String action = switch (next) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            case VOID -> "void";
            default -> throw new ClaimStatusRefusedException();
        };
        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
        if (voidingSettled) refuseVoidOfSettled(sheetId, user, claim);
        else if (!claim.getStatus().canBecome(next)) {
            throw new ClaimStatusRefusedException();
        }
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimDeferredException();
        }
        if (next == ClaimStatus.SETTLED && !judgedOnOriginal && claim.isOpenedOrEditedBy(user)) {
            throw new ClaimSettledByOpenerException();
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN && person.flagOn(sheets.today(sheetId)) != null
                && settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimFlaggedException();
        }
        // Settling freezes the late charge of the moment (as of a date: of the end of that date) into the settled due.
        BigDecimal settling = next != ClaimStatus.SETTLED ? null
                : asOf != null ? asOf.figure() : chargedFigureOf(sheetId, person, claim);
        if (next == ClaimStatus.SETTLED && !judgedOnOriginal) refuseUnproved(sheetId, person, claim, settling);
        BigDecimal opening = next == ClaimStatus.OPEN ? chargedFigureOf(sheetId, person, claim) : null;
        if (next == ClaimStatus.OPEN) refuseUnnoted(sheetId, claim, opening);
        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, person, settling)) next = ClaimStatus.PENDING;
        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonForVoid(sheetId, reason) : null;
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        refuseIfClosed(sheetId, claim.getDueBy());
        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
        if (next == ClaimStatus.OPEN && overReviewThreshold(sheetId, claim, opening)) next = ClaimStatus.REVIEW;
        switch (next) {
            case OPEN -> {
                number(numbering, claim);
                claim.setOpenedBy(user.strip());
            }
            case REVIEW -> {
                claim.setOpenedBy(user.strip());
                claim.setReviewOn(sheets.today(sheetId));
            }
            case SETTLED -> {
                claim.setSettledDue(settling);
                claim.setSettleBatch(null);
            }
            case PENDING -> claim.setSettleBatch(null);
            case VOID -> claim.setVoidReason(voidReason);
            default -> {}
        }
        claim.setStatus(next);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case REVIEW -> "CLAIM_REVIEW";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        String due = next == ClaimStatus.SETTLED
                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
                : voidingSettled ? " reversed=" + figureText(saved.getSettledDue())
                : "";
        if (voidReason != null) due += " reason=" + voidReason;
        if (next == ClaimStatus.SETTLED && asOf != null) due += " on=" + asOf.on();
        record(event, sheetId, user, person, saved, saved.getNumber(), due);
        if (next == ClaimStatus.SETTLED) notifyWatchers(sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Delete a DRAFT claim: DELETED, it counts nowhere and cannot be edited, opened or voided until restored.
     * Refused for a claim in any other status, one another user's editor locks, or one due inside a closed period.
     */
    @Transactional
    public Claim delete(String sheetId, String user, Long id) {
        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (!claim.getStatus().canBecome(ClaimStatus.DELETED)) throw new ClaimStatusRefusedException();
        if (claim.isLockedAgainst(user)) throw new ClaimLockedException();
        refuseIfClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        claim.setLockedBy(null);
        claim.setStatus(ClaimStatus.DELETED);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_DELETED", sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Restore a DELETED claim to DRAFT, on the same sheet's today it was deleted. Refused for a claim in any
     * other status, on a later day, or for one due inside a closed period.
     */
    @Transactional
    public Claim restore(String sheetId, String user, Long id) {
        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusRefusedException();
        if (!sheets.today(sheetId).equals(claim.deletedOn())) throw new ClaimRestoreWindowException();
        refuseIfClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        claim.setStatus(ClaimStatus.DRAFT);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_RESTORED", sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** A steward other than its opener or last editor approves a PENDING claim: SETTLED, its due fixed at its live due now. */
    @Transactional
    public Claim approve(String sheetId, String user, Long id) {
        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = pendingForSteward(sheetId, user, id);
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimApprovedByOpenerException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        refuseIfClosed(sheetId, claim.getDueBy());
        BigDecimal settling = chargedFigureOf(sheetId, person, claim);
        refuseUnproved(sheetId, person, claim, settling);
        claim.setSettledDue(settling);
        claim.setStatus(ClaimStatus.SETTLED);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
        notifyWatchers(sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward reviews a REVIEW claim: OPEN, given the sheet's next number, still opened by the user who
     * opened it. Refused for anyone else, a claim in any other status, or one due inside a closed period.
     */
    @Transactional
    public Claim review(String sheetId, String user, Long id) {
        // Numbering locks the sheet first, so the claim is read once no other change is under way.
        Sheet numbering = sheets.lockForNumbering(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.REVIEW) throw new ClaimStatusRefusedException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        refuseIfClosed(sheetId, claim.getDueBy());
        refuseOverCap(sheetId, claim);
        number(numbering, claim);
        claim.setStatus(ClaimStatus.OPEN);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_REVIEWED", sheetId, user, person, saved, null, "");
        record("CLAIM_OPENED", sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** A steward rejects a PENDING claim with a reason: OPEN again, bound by its person's last statement if it was. */
    @Transactional
    public Claim reject(String sheetId, String user, Long id, String reason) {
        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = pendingForSteward(sheetId, user, id);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        refuseIfClosed(sheetId, claim.getDueBy());
        claim.setStatus(ClaimStatus.OPEN);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber(), " reason=" + reason);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
     * late charge as of today). Refused for anyone
     * else, a claim in any other status, or one due inside a closed period.
     */
    @Transactional
    public Claim resettle(String sheetId, String user, Long id) {
        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        refuseIfClosed(sheetId, claim.getDueBy());
        BigDecimal old = claim.getSettledDue();
        BigDecimal figure = LateCharge.withChargeAsOpen(claim, floored(sheetId, claim, dueOf(sheetId, person, claim)),
                sheets.today(sheetId), graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d),
                roundingOf(sheetId, claim));
        claim.setSettledDue(figure);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
                " old=" + figureText(old) + " new=" + figureText(figure));
        notifyWatchers(sheetId, user, person, saved);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
     * statement stays bound; its period, which follows its due-by, stays too. While the sheet numbers by
     * period and the claim was numbered within another period, it takes the next number of its due-by's
     * period, its old number never given again. Refused for anyone else, a claim in any other status, one
     * due inside a closed period, or a new date after its person's retirement date.
     */
    @Transactional
    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
        // Numbering locks the sheet first, so the claim is read once no other change is under way.
        Sheet numbering = sheets.lockForNumbering(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
        refuseIfClosed(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
        if (!person.mayClaimOn(date)) throw new PersonRetiredException();
