564	    /**
565	     * Reassign a claim by the rules above; a bulk move ({@code bulk}) takes a claim already its new
566	     * person's as moved to them again rather than refusing it.
567	     */
568	    @Transactional
569	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean bulk) {
570	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
571	        Sheet numbering = sheets.lockForNumbering(sheetId);
572	        RollupService.Snapshot before = rollup.snapshot(sheetId);
573	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
574	        ClaimStatus status = claim.getStatus();
575	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
576	        if (!settings.mayDo(sheetId, user, "reassign")) throw new ClaimNotPermittedException();
577	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
578	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
579	        if (!bulk && from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
580	        refuseIfClosed(sheetId, claim.getDueBy());
581	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
582	        claim.unstate(sheets.today(sheetId));
583	        claim.moveTo(to.getId(), claims.nextListed());
584	        if (claim.getNumber() != null) {
585	            if (claim.getNumberPeriod() != null) {
586	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
587	            }
588	            number(numbering, claim);
589	        }
590	        Claim saved = claims.saveAndFlush(claim);
591	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
592	                " from=" + from.getName() + " to=" + to.getName());
593	        rollup.recordChanges(sheetId, user, before);
594	        return saved;
595	    }
