763	     * Remind an OPEN or PENDING claim: a REMIND line is written and the claim is reminded on the sheet's
764	     * today. Refused for a claim in any other status, or one already reminded on the sheet's today. When the
765	     * sheet has an escalation gap and the previous reminder was at least that many days before today, an
766	     * ESCALATE line follows, once per claim ever.
767	     */
768	    @Transactional
769	    public Claim remind(String sheetId, String user, Long id) {
770	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
771	        RollupService.Snapshot before = rollup.snapshot(sheetId);
772	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
773	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
774	        LocalDate today = sheets.today(sheetId);
775	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
776	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
777	        Integer escalateAfter = settings.escalateAfter(sheetId);
778	        boolean escalates = escalateAfter != null && !claim.isEscalated() && claim.getRemindedOn() != null
779	                && !claim.getRemindedOn().plusDays(escalateAfter).isAfter(today);
780	        claim.remind(today);
781	        if (escalates) claim.escalate();
782	        Claim saved = claims.saveAndFlush(claim);
783	        record("REMIND", sheetId, user, person, saved);
784	        if (escalates) record("ESCALATE", sheetId, user, person, saved);
785	        rollup.recordChanges(sheetId, user, before);
786	        return saved;
787	    }
