789	    /**
790	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force on
791	     * its date (its person's grade's then when set, else the sheet's); a due of n/a is within any, and no
792	     * threshold means none is needed. While the sheet has proof kinds, it needs a proof of each listed kind instead.
793	     */
794	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
795	        if (due == null) return;
796	        List<String> kinds = settings.proofKinds(sheetId);
797	        boolean proved = kinds.isEmpty() ? claim.getProofs() > 0 : kinds.stream().allMatch(k -> claim.proofsOf(k) > 0);
798	        if (proved) return;
799	        BigDecimal threshold = settings.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
800	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
801	    }
