804	     * Refuse opening a claim with an empty note whose due is above the note threshold in force on its date;
805	     * a due of n/a is within any, and no threshold means no note is needed.
806	     */
807	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
808	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
809	        BigDecimal threshold = settings.noteThresholdOn(sheetId, claim.getDate());
810	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
811	    }
