815	     * date; a due of n/a is within any, and no threshold means none goes to review.
816	     */
817	    private boolean overReviewThreshold(String sheetId, Claim claim, BigDecimal due) {
818	        if (due == null) return false;
819	        BigDecimal threshold = settings.reviewThresholdOn(sheetId, claim.getDate());
820	        return threshold != null && due.compareTo(threshold) > 0;
