844	    /**
845	     * Give an opened claim its number: FY&lt;year&gt;-&lt;n&gt;, the next in the fiscal year its due-by falls in
846	     * (by the sheet's fiscal start month) after the last given in that year anywhere in the sheet's tree
847	     * (its topmost ancestor and every descendant of that), or while the sheet numbers by period, the next
848	     * within the period its due-by falls in (in no period: the next in the sheet's X sequence).
849	     */
850	    private void number(Sheet sheet, Claim claim) {
851	        if (!sheet.numbersByPeriod()) {
852	            int year = fiscalYearOf(sheet, claim.getDueBy() != null ? claim.getDueBy() : claim.getDate());
853	            claim.setFiscalNumber(year, sheets.nextFiscalNumberInTree(sheet.getId(), year));
854	            return;
855	        }
856	        String period = periodOn(sheet.getId(), claim.getDueBy());
857	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
858	    }
859	
860	    /** The fiscal year the date falls in, by the calendar year of its first day (the sheet's start month). */
861	    private static int fiscalYearOf(Sheet sheet, LocalDate date) {
862	        return date.getMonthValue() >= sheet.getFiscalStartMonth() ? date.getYear() : date.getYear() - 1;
863	    }
864	
865	    /**
866	     * The terms a claim of the person created on the day (the sheet's today then) is fixed with: their own
867	     * terms in force that day, else those of the grade they had that day, else the sheet's that day. Its
868	     * due-by is the terms-th business day after its date (skipping weekends and the sheet's holidays).
869	     */
870	    private int termsOf(String sheetId, Person person, LocalDate on) {
871	        Integer own = person.termsOn(on);
872	        return own != null ? own : settings.termsFor(sheetId, person.gradeOn(on), on);
873	    }
874	
875	    /**
876	     * Refuse to open a claim whose due-by falls in a period with a cap when its person already has that
877	     * many OPEN or PENDING claims due inside the period.
878	     */
879	    private void refuseOverCap(String sheetId, Claim claim) {
880	        Period period = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
881	                .filter(p -> p.contains(claim.getDueBy()))
882	                .findFirst().orElse(null);
883	        if (period == null || period.getCap() == null) return;
884	        long open = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
885	                .filter(c -> !c.getId().equals(claim.getId()))
886	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
887	                .filter(c -> period.contains(c.getDueBy()))
888	                .count();
889	        if (open >= period.getCap()) throw new ClaimCapReachedException();
890	    }
891	
892	    /** The name of the sheet's period the date falls in; empty when in none. */
893	    private String periodOn(String sheetId, LocalDate date) {
894	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
895	                .filter(p -> p.contains(date))
896	                .map(Period::getName)
897	                .findFirst().orElse("");
898	    }
899	
900	    /**
901	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's last
902	     * statement (late charge and floor included), else its rate figure (no floor, no charge); null when it
903	     * has none.
904	     */
905	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
906	        if (claim.getSettledDue() != null) return claim.getSettledDue();
907	        if (claim.isBound()) return claim.getStatedDue();
908	        return dueOf(sheetId, person, claim);
909	    }
910	
911	    /**
912	     * A claim's due now: the greater of the floor in force on its date and its figure, with the late
913	     * charge worked out on that floored figure on top while it is overdue (a correction: neither); a settled due as fixed; null when it
914	     * has none. A due bound by a statement is shown as bound, its charge no longer following today.
915	     */
916	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
917	        return charged(sheetId, person, claim, figureOf(sheetId, person, claim));
918	    }
919	
920	    /** What a rate preview finds: how many claims' dues would change, and by how much in all. */
921	    public record RatePreview(int count, BigDecimal diff) {}
922	
923	    /**
924	     * How many OPEN and PENDING claims of people on the grade (the one in force on the claim's date) would show
925	     * a different due were the percent the grade's rate on every date, and the sum of new minus current dues
926	     * (a due of n/a counts as 0). A claim bound by a statement does not change. Nothing is stored.
927	     */
928	    @Transactional(readOnly = true)
929	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
930	        int count = 0;
931	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
932	        Map<Long, Person> byId = new HashMap<>();
933	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) byId.put(p.getId(), p);
934	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
935	            if (!claim.getStatus().isOpen() || claim.isBound()) continue;
936	            Person person = byId.get(claim.getPersonId());
937	            if (person == null || !grade.equals(person.gradeOn(claim.getDate()))) continue;
938	            BigDecimal current = chargedFigureOf(sheetId, person, claim);
939	            BigDecimal figure = claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
940	            BigDecimal next = charged(sheetId, person, claim, figure);
941	            BigDecimal was = current == null ? BigDecimal.ZERO.setScale(2) : current;
942	            BigDecimal now = next == null ? BigDecimal.ZERO.setScale(2) : next;
943	            if (current == null || now.compareTo(was) != 0) {
944	                count++;
945	                diff = diff.add(now.subtract(was));
946	            }
947	        }
948	        return new RatePreview(count, diff.setScale(2));
949	    }
950	
951	    /**
952	     * The claim's due with the figure given: floored, with its late charge on the floored figure while overdue; a settled due as
953	     * fixed, a due bound by a statement as bound.
954	     */
955	    private BigDecimal charged(String sheetId, Person person, Claim claim, BigDecimal figure) {
956	        if (claim.getSettledDue() != null) return claim.getSettledDue();
957	        if (claim.isBound()) return claim.getStatedDue();
958	        return LateCharge.withCharge(claim, floored(sheetId, claim, figure), sheets.today(sheetId),
959	                graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim));
960	    }
961	
962	    /** The grace days of the person's grade on the claim's date, in force on it; 0 when none. */
963	    private int graceOf(String sheetId, Person person, Claim claim) {
964	        return settings.graceOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
965	    }
966	
967	    /** The due at least the sheet's floor in force on the claim's date, unless a correction; null when none. */
968	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
969	        if (due == null || claim.isCorrection()) return due;
970	        return due.max(settings.floorOn(sheetId, claim.getDate()));
971	    }
972	
973	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
974	    private RoundingMode roundingOf(String sheetId, Claim claim) {
975	        LocalDate basis = Rounding.basisOf(claim,
976	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
977	        return Rounding.of(basis, settings.roundingOn(sheetId, basis), settings.policyDate(sheetId), sheets.today(sheetId));
978	    }
979	
980	    /**
981	     * A claim's rate figure: its amount times the rate on its date of its person's grade in force on it (of those
982	     * that apply to the claim: no forward-only rate saved after it was added), rounded to cents as {@link Rounding}
983	     * has it, with no floor; null with no rate.
984	     */
985	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
986	        RoundingMode rounding = roundingOf(sheetId, claim);
987	        return rates.onFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), claim.getAdded())
988	                .map(Rate::getPct)
989	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
990	                .orElse(null);
991	    }
992	
993	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
994	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
995	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
996	    }
997	
998	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
999	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
1000	    }
1001	
1002	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
1003	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
1004	            String extra) {
1005	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
1006	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
1007	                + (number != null ? " number=" + number : "") + extra);
1008	    }
1009	
1010	    /**
1011	     * Take a person's claims, as they arrive with them from another sheet, onto the sheet (locked for
1012	     * numbering by the caller): each loses what {@link Claim#transferTo} drops, and each that had a number
1013	     * takes the sheet's next, in the order they were opened (by the sheet's today each was first opened on,
1014	     * then in the order they were added). A correction, or a claim split off another, then names the
1015	     * number its claim was given. Their tags are kept among those used on the sheet.
1016	     */
1017	    @Transactional
1018	    public void receive(Sheet to, List<Claim> arriving) {
1019	        Map<Long, String> old = new HashMap<>();
1020	        for (Claim claim : arriving) {
1021	            old.put(claim.getId(), claim.getNumber());
1022	            claim.transferTo(to.getId(), claims.nextAdded());
1023	        }
1024	        claims.saveAllAndFlush(arriving);
1025	        numberAfresh(to, arriving, old);
1026	        for (Claim claim : arriving) keepTags(to.getId(), claim);
1027	        claims.saveAllAndFlush(arriving);
1028	    }
1029	
1030	    /**
1031	     * Number afresh, on the sheet (locked for numbering by the caller), the claims that had a number before
1032	     * ({@code oldNumbers}, by claim id): each takes the sheet's next, in the order they were opened (by the
1033	     * sheet's today each was first opened on, then in the order they were added). A correction, or a claim
1034	     * split off another, then names the number its claim was given.
1035	     */
1036	    @Transactional
1037	    public void numberAfresh(Sheet to, List<Claim> numbering, Map<Long, String> oldNumbers) {
1038	        List<Claim> numbered = numbering.stream().filter(c -> oldNumbers.get(c.getId()) != null)
1039	                .sorted(Comparator.comparing(Claim::openedOn,
1040	                        Comparator.nullsFirst(Comparator.naturalOrder()))
1041	                        .thenComparing(Claim::getId))
1042	                .toList();
1043	        Map<String, String> renumbered = new HashMap<>();
1044	        for (Claim claim : numbered) {
1045	            number(to, claim);
1046	            claims.saveAndFlush(claim);
1047	            renumbered.put(oldNumbers.get(claim.getId()), claim.getNumber());
1048	        }
1049	        for (Claim claim : numbering) {
1050	            if (claim.getCorrects() != null) {
1051	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
1052	            }
1053	            if (claim.getSplitFrom() != null) {
1054	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
1055	            }
1056	        }
1057	        claims.saveAllAndFlush(numbering);
1058	    }
1059	
1060	    /** Keep each of the claim's tags among those ever used on the sheet. */
1061	    private void keepTags(String sheetId, Claim claim) {
1062	        keepTags(sheetId, claim.getTags());
1063	    }
1064	
1065	    /** Keep each of the tags (a claim's or a person's) among those ever used on the sheet. */
1066	    @Transactional
1067	    public void keepTags(String sheetId, List<String> tagged) {
1068	        for (String tag : tagged) {
1069	            if (!tags.existsBySheetIdAndTag(sheetId, tag)) tags.save(new ClaimTag(sheetId, tag));
1070	        }
1071	    }
1072	
1073	    /** Refuse a reference (null: none) that a claim on the sheet other than this one (null: any) already carries. */
1074	    private void refuseIfRefUsed(String sheetId, Long self, String ref) {
1075	        if (ref == null) return;
1076	        claims.findBySheetIdAndRefKey(sheetId, Claim.refKeyOf(ref))
1077	                .filter(other -> !other.getId().equals(self))
1078	                .ifPresent(other -> { throw new DuplicateClaimRefException(); });
1079	    }
1080	
1081	    /**
1082	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
1083	     * one but is not a correction. A correction may not exceed what remains of the claim it corrects: its
1084	     * amount less the corrections already made against it (VOID or DELETED ones, and this claim (null:
1085	     * none) itself, left out).
1086	     */
1087	    private void refuseUnlessCorrects(String sheetId, Long personId, Long self, BigDecimal amount, String corrects) {
1088	        if (amount.signum() >= 0) {
1089	            if (corrects != null) throw new CorrectionRefusedException();
1090	            return;
1091	        }
1092	        if (corrects == null) throw new CorrectionRefusedException();
1093	        List<Claim> ofPerson = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1094	        Claim target = ofPerson.stream()
1095	                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
1096	                .findFirst().orElseThrow(CorrectionRefusedException::new);
1097	        BigDecimal remaining = ofPerson.stream()
1098	                .filter(c -> corrects.equals(c.getCorrects()) && !c.getId().equals(self)
1099	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
1100	                .map(Claim::getAmount)
1101	                .reduce(target.getAmount(), BigDecimal::add);
1102	        if (amount.negate().compareTo(remaining) > 0) throw new CorrectionRefusedException();
1103	    }
1104	
1105	    /**
1106	     * Whether a clerk settles a claim whose due is above the clerk limit in force: its person's grade's on the
1107	     * sheet's today when one is set, else the sheet's; a due of n/a is within any.
1108	     */
1109	    private boolean overClerkLimit(String sheetId, String user, Person person, BigDecimal due) {
1110	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
1111	        BigDecimal limit = settings.clerkLimitFor(sheetId, person.gradeOn(sheets.today(sheetId)));
1112	        return limit != null && due != null && due.compareTo(limit) > 0;
1113	    }
1114	
1115	    /** Refuse a change to a claim whose due-by falls inside a closed period; the caller holds the sheet's lock. */
1116	    private void refuseIfClosed(String sheetId, LocalDate date) {
1117	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
1118	    }
1119	
1120	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
1121	        return date != null ? date : sheets.today(sheetId);
1122	    }
1123	
1124	    /** A new claim's date: the one given, else the entry date while set, else the sheet's today. */
1125	    public LocalDate dateOrEntryDate(String sheetId, LocalDate date) {
1126	        if (date != null) return date;
1127	        LocalDate entryDate = settings.entryDate(sheetId);
1128	        return entryDate != null ? entryDate : sheets.today(sheetId);
1129	    }
1130	}
